import json, os, tempfile
from settings import save
with tempfile.TemporaryDirectory() as d:
    p = os.path.join(d, "s.json")
    before = b'{"orig": true}'
    with open(p, "wb") as f:
        f.write(before)
    for how, raised, data in failing_saves(save, p):
        with open(p, "rb") as f:
            now = f.read()
        if raised:
            assert now == before, ("a save that raised changed the file", how, now[:60])
        else:
            try:
                ok = same(json.loads(now.decode("utf-8")), data)
            except ValueError:
                ok = False
            assert ok, ("a save that returned normally did not write its data", how, now[:60])
            before = now
    q = os.path.join(d, "is-a-dir")
    os.mkdir(q)
    open(os.path.join(q, "inner"), "w").close()
    try:
        save(q, {"x": 1})
    except Exception:
        pass
    assert os.path.isdir(q) and os.listdir(q) == ["inner"], ("a save that raised changed what was at path", os.listdir(d))
    save(p, {"x": [1, 2, 3]})
    with open(p, "rb") as f:
        after = f.read()
    assert json.loads(after.decode("utf-8")) == {"x": [1, 2, 3]}, after[:60]
